const botao = document.querySelector('#alternar');
const app = document.querySelector('#app');

botao.addEventListener('click', () => {
  app.classList.toggle('escuro');
});

const botao = document.querySelector('#curtir');
const total = document.querySelector('#total');
let curtidas = 0;

botao.addEventListener('click', () => {
  curtidas += 1;
  total.textContent = curtidas;
});

const carrinho = document.querySelector('#carrinho');

carrinho.addEventListener('click', (evento) => {
  const botao = evento.target.closest('.remover');
  if (!botao) {
    return;
  }
  botao.closest('li').remove();
});

const filtro = document.querySelector('#filtro');
const itens = document.querySelectorAll('#lista li');

filtro.addEventListener('input', () => {
  const termo = filtro.value.trim().toLowerCase();

  itens.forEach((item) => {
    const combina = item.textContent.toLowerCase().includes(termo);
    item.hidden = !combina;
  });
});
